import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/inventory/search', extractTenant, async (req, res) => {
  try {
    const { category, warehouse, sort_by, direction } = req.query;

    let baseQuery = `SELECT i.id, i.name, i.sku, i.quantity, i.unit_price, 
                     w.name as warehouse_name, c.name as category_name
                     FROM inventory_items i
                     JOIN warehouses w ON i.warehouse_id = w.id
                     JOIN categories c ON i.category_id = c.id
                     WHERE i.tenant_id = $1`;

    const params = [req.tenantId];
    let paramIdx = 2;

    if (category) {
      baseQuery += ` AND c.name = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (warehouse) {
      baseQuery += ` AND w.name = $${paramIdx}`;
      params.push(warehouse);
      paramIdx++;
    }

    // Sort column - validated against allowlist
    const allowedSorts = ['name', 'sku', 'quantity', 'unit_price', 'warehouse_name', 'category_name'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'name';

    // Direction - NOT properly validated, injectable
    const sortDirection = direction || 'ASC';
    baseQuery += ` ORDER BY ${sortCol} ${sortDirection}`;

    baseQuery += ' LIMIT 100';

    const result = await pool.query(baseQuery, params);
    res.json({ items: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/inventory/bulk-update', extractTenant, async (req, res) => {
  const { updates } = req.body;
  if (!Array.isArray(updates) || updates.length > 50) {
    return res.status(400).json({ error: 'Invalid updates array' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const results = [];

    for (const update of updates) {
      const { item_id, field, value } = update;
      // Field validation
      const mutableFields = ['quantity', 'unit_price', 'name', 'sku'];
      if (!mutableFields.includes(field)) continue;

      const q = `UPDATE inventory_items SET ${field} = $1, updated_at = NOW() 
                 WHERE id = $2 AND tenant_id = $3 RETURNING id`;
      const r = await client.query(q, [value, item_id, req.tenantId]);
      if (r.rows.length > 0) results.push(r.rows[0].id);
    }

    await client.query('COMMIT');
    res.json({ updated: results });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Bulk update failed' });
  } finally {
    client.release();
  }
});

// Export endpoint - generates CSV
app.get('/api/v2/inventory/export', extractTenant, async (req, res) => {
  const { format, filter_expr } = req.query;

  let query = `SELECT * FROM inventory_items WHERE tenant_id = $1`;
  const params = [req.tenantId];

  // Additional filter expression - appended directly
  if (filter_expr) {
    query += ` AND ${filter_expr}`;
  }

  try {
    const result = await pool.query(query, params);
    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      const header = Object.keys(result.rows[0] || {}).join(',');
      const rows = result.rows.map(r => Object.values(r).join(','));
      res.send([header, ...rows].join('\n'));
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0');
